import Database from "better-sqlite3";
import path from "path";

const dbPath = path.resolve("/home/user/qwik-app/form_builder.sqlite");

const db = new Database(dbPath);

// Initialize database tables
db.exec(`
  CREATE TABLE IF NOT EXISTS forms (
    id TEXT PRIMARY KEY,
    schema TEXT
  );

  CREATE TABLE IF NOT EXISTS submissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    form_id TEXT,
    data TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`);

export default db;

export interface FieldSchema {
  name: string;
  type: "string" | "number" | "boolean";
  required?: boolean;
  min?: number;
  max?: number;
  minLength?: number;
  maxLength?: number;
  pattern?: string;
}

export interface FormSchema {
  fields: FieldSchema[];
}

export interface ValidationResult {
  success: boolean;
  errors: Record<string, string>;
  data: Record<string, any>;
}

export function validateSubmission(schema: FormSchema, body: any): ValidationResult {
  const errors: Record<string, string> = {};
  const validatedData: Record<string, any> = {};

  const payload = body || {};

  for (const field of schema.fields) {
    const { name, type, required, min, max, minLength, maxLength, pattern } = field;
    const rawValue = payload[name];

    if (type === "boolean") {
      // Parse boolean
      let parsedValue = false;
      if (rawValue === true || rawValue === "true" || rawValue === "on") {
        parsedValue = true;
      }

      if (required && !parsedValue) {
        errors[name] = `${name} must be checked`;
      } else {
        validatedData[name] = parsedValue;
      }
    } else if (type === "number") {
      // Parse number
      const isEmpty = rawValue === undefined || rawValue === null || rawValue === "";

      if (isEmpty) {
        if (required) {
          errors[name] = `${name} is required`;
        } else {
          validatedData[name] = null;
        }
      } else {
        const parsedValue = Number(rawValue);
        if (isNaN(parsedValue)) {
          errors[name] = `${name} must be a number`;
        } else {
          // Check min/max
          if (min !== undefined && parsedValue < min) {
            errors[name] = `${name} must be at least ${min}`;
          } else if (max !== undefined && parsedValue > max) {
            errors[name] = `${name} must be at most ${max}`;
          } else {
            validatedData[name] = parsedValue;
          }
        }
      }
    } else if (type === "string") {
      // Parse string
      const isEmpty = rawValue === undefined || rawValue === null || rawValue === "";

      if (isEmpty) {
        if (required) {
          errors[name] = `${name} is required`;
        } else {
          validatedData[name] = "";
        }
      } else {
        const strValue = String(rawValue);
        if (minLength !== undefined && strValue.length < minLength) {
          errors[name] = `${name} must be at least ${minLength} characters`;
        } else if (maxLength !== undefined && strValue.length > maxLength) {
          errors[name] = `${name} must be at most ${maxLength} characters`;
        } else if (pattern !== undefined) {
          try {
            const regex = new RegExp(pattern);
            if (!regex.test(strValue)) {
              errors[name] = `${name} is invalid`;
            } else {
              validatedData[name] = strValue;
            }
          } catch (e) {
            // If pattern is invalid regex, we might just skip or handle
            validatedData[name] = strValue;
          }
        } else {
          validatedData[name] = strValue;
        }
      }
    }
  }

  const success = Object.keys(errors).length === 0;
  return {
    success,
    errors,
    data: success ? validatedData : {},
  };
}

import type { RequestHandler } from "@builder.io/qwik-city";
import db from "../../../../db";
import { validateSubmission } from "../../../../validator";

export const onPost: RequestHandler = async (event) => {
  const { params, parseBody, json } = event;
  const { id } = params;

  // 1. Fetch the form schema for :id from the SQLite forms table
  let row: { schema: string } | undefined;
  try {
    row = db.prepare("SELECT schema FROM forms WHERE id = ?").get(id) as { schema: string } | undefined;
  } catch (err) {
    return json(500, { success: false, error: "Database error" });
  }

  // 2. If the form ID does not exist, return a 404 Not Found response
  if (!row) {
    return json(404, { success: false, error: "Form not found" });
  }

  let schema;
  try {
    schema = JSON.parse(row.schema);
  } catch (err) {
    return json(500, { success: false, error: "Invalid form schema in database" });
  }

  // 3. Parse the body (supports application/json and application/x-www-form-urlencoded)
  let body: any;
  try {
    body = await parseBody();
  } catch (err) {
    return json(400, { success: false, error: "Invalid request body" });
  }

  // 4. Validate the submitted data against the schema
  const validation = validateSubmission(schema, body);

  if (!validation.success) {
    // Validation Failure Response
    return json(400, {
      success: false,
      errors: validation.errors,
    });
  }

  // 5. Validation Success Response: Save submission to table
  try {
    const stmt = db.prepare("INSERT INTO submissions (form_id, data) VALUES (?, ?)");
    const result = stmt.run(id, JSON.stringify(validation.data));
    const submissionId = Number(result.lastInsertRowid);

    return json(200, {
      success: true,
      submissionId,
    });
  } catch (err) {
    return json(500, { success: false, error: "Failed to save submission" });
  }
};

import { component$, $, useStore, useSignal } from "@builder.io/qwik";
import { routeLoader$ } from "@builder.io/qwik-city";
import db from "../../../db";

export const useFormSchema = routeLoader$(async (requestEvent) => {
  const { params, error } = requestEvent;
  const { id } = params;

  let row: { schema: string } | undefined;
  try {
    row = db.prepare("SELECT schema FROM forms WHERE id = ?").get(id) as { schema: string } | undefined;
  } catch (err) {
    throw error(500, "Database error");
  }

  if (!row) {
    throw error(404, "Form not found");
  }

  try {
    return {
      id,
      schema: JSON.parse(row.schema) as {
        fields: Array<{
          name: string;
          type: "string" | "number" | "boolean";
          required?: boolean;
          min?: number;
          max?: number;
          minLength?: number;
          maxLength?: number;
          pattern?: string;
        }>;
      },
    };
  } catch (err) {
    throw error(500, "Invalid form schema in database");
  }
});

export default component$(() => {
  const formSchema = useFormSchema();
  const errors = useStore<Record<string, string>>({});
  const successMessage = useSignal<string | null>(null);

  const handleSubmit = $(async (event: Event) => {
    event.preventDefault();

    // Clear previous errors/success message
    for (const key of Object.keys(errors)) {
      delete errors[key];
    }
    successMessage.value = null;

    const form = event.target as HTMLFormElement;
    const formData = new FormData(form);

    // Convert FormData to URLSearchParams for application/x-www-form-urlencoded
    const body = new URLSearchParams();
    for (const [key, value] of formData.entries()) {
      body.append(key, value as string);
    }

    // Since unchecked checkboxes are not submitted by default, we don't need to append them.
    // The server handles missing boolean fields as false.

    try {
      const response = await fetch(`/forms/${formSchema.value.id}/submit`, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: body.toString(),
      });

      const result = await response.json();

      if (!response.ok || !result.success) {
        if (result.errors) {
          for (const [key, val] of Object.entries(result.errors)) {
            errors[key] = val as string;
          }
        } else {
          errors["_form"] = result.error || "An error occurred during submission.";
        }
      } else {
        successMessage.value = `Submission successful! Submission ID: ${result.submissionId}`;
        form.reset();
      }
    } catch (err) {
      errors["_form"] = "Failed to submit form.";
    }
  });

  const { id, schema } = formSchema.value;

  return (
    <div style={{ maxWidth: "600px", margin: "40px auto", padding: "20px", fontFamily: "sans-serif" }}>
      <h1 style={{ marginBottom: "20px" }}>Dynamic Form: {id}</h1>

      {successMessage.value && (
        <div style={{ padding: "15px", backgroundColor: "#d4edda", color: "#155724", borderRadius: "4px", marginBottom: "20px" }}>
          {successMessage.value}
        </div>
      )}

      {errors["_form"] && (
        <div style={{ padding: "15px", backgroundColor: "#f8d7da", color: "#721c24", borderRadius: "4px", marginBottom: "20px" }}>
          {errors["_form"]}
        </div>
      )}

      <form method="POST" action={`/forms/${id}/submit`} onSubmit$={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {schema.fields.map((field) => (
          <div key={field.name} style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
            <label for={field.name} style={{ fontWeight: "bold" }}>
              {field.name}
              {field.required && <span style={{ color: "red" }}> *</span>}
            </label>

            {field.type === "string" && (
              <input
                type="text"
                id={field.name}
                name={field.name}
                style={{ padding: "8px", borderRadius: "4px", border: errors[field.name] ? "1px solid red" : "1px solid #ccc" }}
              />
            )}

            {field.type === "number" && (
              <input
                type="number"
                id={field.name}
                name={field.name}
                style={{ padding: "8px", borderRadius: "4px", border: errors[field.name] ? "1px solid red" : "1px solid #ccc" }}
              />
            )}

            {field.type === "boolean" && (
              <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                <input
                  type="checkbox"
                  id={field.name}
                  name={field.name}
                />
                <span>Enable {field.name}</span>
              </div>
            )}

            {errors[field.name] && (
              <span style={{ color: "red", fontSize: "0.85rem", marginTop: "2px" }}>
                {errors[field.name]}
              </span>
            )}
          </div>
        ))}

        <button
          type="submit"
          style={{
            padding: "10px 15px",
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
            fontWeight: "bold",
            marginTop: "10px"
          }}
        >
          Submit
        </button>
      </form>
    </div>
  );
});

